local BeaconLightMaker = {}
local PRODUCTS = {
    simple_wood_beacon = { name = "Preprost leseni svetilnik", woodCost = 4, waxCost = 2, ironCost = 1, time = 5, cost = 150, lightRadius = 50, happiness = 1, description = "Preprost leseni svetilnik za razgled." }
    , iron_reinforced_beacon = { name = "Železnookrepljen svetilnik", woodCost = 3, ironCost = 2, waxCost = 2, time = 8, cost = 380, lightRadius = 65, happiness = 2, prestige = 2, description = "Železnookrepljen svetilnik za trgovce." },
    silver_trimmed_beacon = { name = "Srebrnoobrobljeni svetilnik", woodCost = 3, ironCost = 2, silverCost = 1, waxCost = 2, time = 11, cost = 880, lightRadius = 78, happiness = 2, prestige = 6, description = "Srebrnoobrobljeni svetilnik za plemiče." },
    gold_trimmed_beacon = { name = "Zlatookrasni svetilnik", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, waxCost = 2, time = 15, cost = 2000, lightRadius = 90, happiness = 3, prestige = 14, description = "Zlatookrasni svetilnik za visoke plemiče." },
    jewel_set_beacon = { name = "Draguljasta svetilnik", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, waxCost = 2, jewelCost = 1, time = 19, cost = 4400, lightRadius = 105, happiness = 5, prestige = 27, description = "Svetilnik z draguljem za visoko plemstvo." },
    royal_grand_beacon = { name = "Kraljevski veliki svetilnik", woodCost = 5, ironCost = 3, goldCost = 2, silverCost = 2, waxCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 9500, lightRadius = 125, happiness = 12, prestige = 58, description = "Veliki kraljevski svetilnik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    beacon_workshop = { name = "Svetilniška delavnica", cost = { gold = 280, wood = 160, stone = 140, iron = 6, wax = 6 }, upkeep = 6, qualityBonus = 5 },
    lighting_loft = { name = "Razsvetljena podstrešje", cost = { gold = 1000, wood = 320, stone = 280, silver = 6, iron = 8 }, upkeep = 23, qualityBonus = 18 },
    master_beacon_atelier = { name = "Mojstrski svetilniški atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_lighting_palace = { name = "Kraljevska razsvetljenska palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
BeaconLightMaker.woodStock = 18; BeaconLightMaker.ironStock = 14; BeaconLightMaker.waxStock = 12; BeaconLightMaker.silverStock = 6; BeaconLightMaker.goldStock = 6; BeaconLightMaker.jewelStock = 4; BeaconLightMaker.pearlStock = 4
BeaconLightMaker.productStock = {}; BeaconLightMaker.buildings = {}; BeaconLightMaker.maker = nil; BeaconLightMaker.activeMaking = {}; BeaconLightMaker.totalProducts = 0; BeaconLightMaker.dayTimer = 0
function BeaconLightMaker.init() BeaconLightMaker.woodStock=18; BeaconLightMaker.ironStock=14; BeaconLightMaker.waxStock=12; BeaconLightMaker.silverStock=6; BeaconLightMaker.goldStock=6; BeaconLightMaker.jewelStock=4; BeaconLightMaker.pearlStock=4; BeaconLightMaker.productStock={}; BeaconLightMaker.buildings={}; BeaconLightMaker.maker=nil; BeaconLightMaker.activeMaking={}; BeaconLightMaker.totalProducts=0; BeaconLightMaker.dayTimer=0; print("[BeaconLightMaker] Royal Beacon Light Maker System initialized (6 products, 4 buildings)") end
function BeaconLightMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BeaconLightMaker.maker={name=n or ("Svetilnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svetilnikar najet: %s (spretnost: %d)",BeaconLightMaker.maker.name,s),"success") end; return true end
function BeaconLightMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BeaconLightMaker.build(id) local ok,e=BeaconLightMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BeaconLightMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BeaconLightMaker.getQualityBonus() local b=0; for _,bd in ipairs(BeaconLightMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BeaconLightMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BeaconLightMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and BeaconLightMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.waxCost and BeaconLightMaker.waxStock<(d.waxCost or 0) then return false,"Premalo voska" end; if d.silverCost and BeaconLightMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BeaconLightMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BeaconLightMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BeaconLightMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BeaconLightMaker.buildings==0 then return false,"Potrebna svetilniška delavnica" end; if not BeaconLightMaker.maker then return false,"Potreben svetilnikar" end; return true end
function BeaconLightMaker.make(pt,qty) qty=qty or 1; local ok,e=BeaconLightMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BeaconLightMaker.woodStock=BeaconLightMaker.woodStock-d.woodCost*qty end; if d.ironCost then BeaconLightMaker.ironStock=BeaconLightMaker.ironStock-d.ironCost*qty end; if d.waxCost then BeaconLightMaker.waxStock=BeaconLightMaker.waxStock-d.waxCost*qty end; if d.silverCost then BeaconLightMaker.silverStock=BeaconLightMaker.silverStock-d.silverCost*qty end; if d.goldCost then BeaconLightMaker.goldStock=BeaconLightMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BeaconLightMaker.jewelStock=BeaconLightMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BeaconLightMaker.pearlStock=BeaconLightMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BeaconLightMaker.maker then t=math.max(1,t-math.floor(BeaconLightMaker.maker.skill/12)) end; table.insert(BeaconLightMaker.activeMaking,{id="beacon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,lightRadius=d.lightRadius or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BeaconLightMaker.completeMaking(m) local q=1.0+(BeaconLightMaker.getQualityBonus()/100); if BeaconLightMaker.maker then q=q+(BeaconLightMaker.maker.skill/140) end; q=math.min(2.5,q); BeaconLightMaker.productStock[m.productType]=(BeaconLightMaker.productStock[m.productType] or 0)+m.quantity; BeaconLightMaker.totalProducts=BeaconLightMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BeaconLightMaker.maker then BeaconLightMaker.maker.itemsMade=BeaconLightMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BeaconLightMaker.maker.skill=math.min(100,BeaconLightMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svetilnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"beacon.completed",{productName=m.productName,lightRadius=m.lightRadius,prestige=m.prestige,happiness=m.happiness}) end end
function BeaconLightMaker.update(dt) if not _G.state then return end; BeaconLightMaker.dayTimer=BeaconLightMaker.dayTimer+dt; if BeaconLightMaker.dayTimer>=30 then BeaconLightMaker.dayTimer=0; for i=#BeaconLightMaker.activeMaking,1,-1 do local m=BeaconLightMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BeaconLightMaker.completeMaking(m); table.remove(BeaconLightMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BeaconLightMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BeaconLightMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BeaconLightMaker.getStats() return {woodStock=BeaconLightMaker.woodStock,ironStock=BeaconLightMaker.ironStock,waxStock=BeaconLightMaker.waxStock,silverStock=BeaconLightMaker.silverStock,goldStock=BeaconLightMaker.goldStock,jewelStock=BeaconLightMaker.jewelStock,pearlStock=BeaconLightMaker.pearlStock,productStock=BeaconLightMaker.productStock,numBuildings=#BeaconLightMaker.buildings,hasMaker=BeaconLightMaker.maker~=nil,makerName=BeaconLightMaker.maker and BeaconLightMaker.maker.name or "—",makerSkill=BeaconLightMaker.maker and BeaconLightMaker.maker.skill or 0,activeMaking=#BeaconLightMaker.activeMaking,totalProducts=BeaconLightMaker.totalProducts} end
return BeaconLightMaker
